#!/usr/bin/env bash
# ============================================================================
#  GSZ step111 — editable version names ("Adult"/"Family" type labels).
#  Adds an override layer: bot type KEYS stay immutable (the bot still works),
#  only the customer-facing label changes. New /admin/labels page edits them;
#  overrides apply on the product page chooser + cart order record.
#  Plan labels were already editable in the product editor.
#  Safe + idempotent; restores previous files on any failure.
# ============================================================================
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step111-$TS"
TMP=$(mktemp -d)
PATCHED=(routes/products.js routes/checkout.js server.js views/admin/_shell_top.ejs)
NEW=(lib/typelabels.js routes/adminLabels.js views/admin/labels.ejs)

echo "==> step111: editable version names (type labels)"
mkdir -p "$BK"
for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"

restore() {
  echo "!!  FAILED — restoring previous files"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do
    keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done
    if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi
  done
  pm2 restart gsz >/dev/null 2>&1 || true
  echo "!!  restored. no changes kept."
}
trap 'restore' ERR

echo "" | base64 -d > "$TMP/patch_step111.js"
echo ""   | base64 -d > "$TMP/migrate_step111.js"

echo "==> writing new files"
mkdir -p "$GSZ/lib" "$GSZ/routes" "$GSZ/views/admin"
echo "" | base64 -d > "$GSZ/lib/typelabels.js"
echo "" | base64 -d > "$GSZ/routes/adminLabels.js"
echo "" | base64 -d > "$GSZ/views/admin/labels.ejs"

echo "==> applying patches"
node "$TMP/patch_step111.js" "$GSZ"

echo "==> validating"
for f in server.js routes/products.js routes/checkout.js routes/adminLabels.js lib/typelabels.js; do node --check "$GSZ/$f"; done
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/admin/labels.ejs','views/admin/_shell_top.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"

echo "==> migrating db"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/migrate_step111.js" )

echo "==> restarting app"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
sleep 2

echo "==> health checks"
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
AC=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/admin/labels || true)
[ "$AC" = "200" ] || [ "$AC" = "302" ] && echo "    /admin/labels reachable ($AC): OK" || { echo "    /admin/labels $AC"; false; }
SLUG=$(cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "require('dotenv/config');const{Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:+(process.env.DB_PORT||5432),user:process.env.DB_USER,password:process.env.DB_PASS,database:process.env.DB_NAME});p.query(\"SELECT slug FROM products WHERE active AND NOT hidden ORDER BY id LIMIT 1\").then(function(r){console.log(r.rows[0]?r.rows[0].slug:'');return p.end();}).catch(function(){console.log('')})" 2>/dev/null || true)
if [ -n "$SLUG" ]; then
  PC=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3900/product/$SLUG" || true)
  [ "$PC" = "200" ] && echo "    product page renders ($SLUG): OK" || { echo "    product page $SLUG -> $PC"; false; }
fi

trap - ERR
rm -rf "$TMP"
echo ""
echo "==> step111 OK ✅"
echo "    • New admin page: Version names (/admin/labels) — rename Family / Adult etc."
echo "    • Renames are display-only; the bot still gets the original version, so orders never break."
echo "    • Shows on the product version chooser + the cart order record."
echo "    • Plan labels were already editable in each product's editor."
